import { expect, test } from "bun:test";
import fixture from "../../../../../packages/contract/src/fixtures/salaam-board-read-v1.json";
import { serveSalaamBoardReads } from "./salaam-board-reads";

// The board-read boundary (operator ruling 2026-10-28), tested against what Salaam itself emits
// and accepts: `fixture` is a byte copy of Salaam's test/fixtures/agentpod-board-read-v1.json,
// generated by Salaam's own work status and checked against its own work-read parser. The hub's
// real serving pass runs over Salaam's status; every `salaam.work-read` payload it sends must have
// exactly the answer keys Salaam accepts, within Salaam's bounds.
test("the hub serves Salaam's own status and sends answers Salaam accepts", async () => {
  const run = { runId: "run_abc12345", cardId: "card_0123456789abcdef", boardId: "brd_0123456789abcdef" };
  const sp = {
    context: async () => ({ run: { runId: run.runId, cardId: run.cardId }, card: { id: run.cardId }, handoff: null }),
    attempts: async () => ({ attempts: [] }),
  };
  const library = {
    asAgent: () => ({
      request: async (_m: string, path: string) =>
        path === "/api/v1/search"
          ? Response.json({ results: [] })
          : Response.json({ item: { id: "itm_0123456789abcdef", provenance: { board: "brd_ffffffffffffffff" } }, text: "x" }),
    }),
  };
  const sent: { binding: unknown; answer: Record<string, unknown> }[] = [];
  const binding = { fixture: true };
  await serveSalaamBoardReads({
    status: fixture.status_excerpt,
    binding,
    run,
    agentPrincipal: "prn_" + "a".repeat(20),
    sp: sp as never,
    library: library as never,
    send: async (p) => (sent.push(p as never), { ok: true }),
  });
  // One answer per read Salaam listed, in order, each naming its read.
  const listed = Object.values(fixture.status_excerpt)[0] as { id: string }[];
  expect(sent.length).toBe(4);
  expect(sent.map((p) => p.answer.read_id)).toEqual(listed.map((r) => r.id));
  for (const p of sent) {
    expect(Object.keys(p).sort()).toEqual(["answer", "binding"]);
    expect(p.binding).toBe(binding);
    const a = p.answer;
    expect(Object.keys(a).sort()).toEqual(a.ok === true ? fixture.answer_keys.ok : fixture.answer_keys.refused);
    if (a.ok === true) expect(new TextEncoder().encode(String(a.text)).length).toBeLessThanOrEqual(fixture.max_text_bytes);
    else expect(new TextEncoder().encode(String(a.error)).length).toBeLessThanOrEqual(fixture.max_error_bytes);
  }
  // The library item from another board was refused, in Salaam's refused shape.
  expect(sent[3]!.answer).toMatchObject({ ok: false });
  // Salaam's own example answers have the same shapes the hub produces.
  for (const a of fixture.answers)
    expect(Object.keys(a).sort()).toEqual(a.ok ? fixture.answer_keys.ok : fixture.answer_keys.refused);
});
